using Microsoft.Extensions.Logging;

namespace EdiConsole.Sourcing;

/// <summary>
/// The file source log events (IDs 5xx): the startup check of the folder or the bucket. Source-generated by
/// <see cref="LoggerMessageAttribute"/>: each event has a stable ID and level, and its placeholders become structured
/// fields.
/// </summary>
internal static partial class SourcingLog
{
    [LoggerMessage(EventId = 501, EventName = "FolderNotFound", Level = LogLevel.Error,
        Message = "Folder {Folder} doesn't exist (FileSource:Folder is {Setting}, resolved against the current directory)")]
    public static partial void FolderNotFound(this ILogger logger, string folder, string setting);

    [LoggerMessage(EventId = 502, EventName = "BucketNotFound", Level = LogLevel.Error,
        Message = "Bucket {Bucket} doesn't exist on {Endpoint}. Create it, or fix S3Source:BucketName. " +
                  "moto forgets its buckets when it stops.")]
    public static partial void BucketNotFound(this ILogger logger, string bucket, string endpoint);

    [LoggerMessage(EventId = 503, EventName = "S3Unreachable", Level = LogLevel.Error,
        Message = "Nothing answered at {Endpoint}. Start moto if you use it, or check S3Source:ServiceUrl and the network. " +
                  "Reason: {Reason}")]
    public static partial void S3Unreachable(this ILogger logger, string endpoint, string reason);

    [LoggerMessage(EventId = 504, EventName = "S3RequestNotSent", Level = LogLevel.Error,
        Message = "The request for bucket {Bucket} wasn't sent, most often because no AWS credentials were found. " +
                  "Set AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY (any values for moto), or use a profile or a role. " +
                  "Reason: {Reason}")]
    public static partial void S3RequestNotSent(this ILogger logger, string bucket, string reason);

    [LoggerMessage(EventId = 505, EventName = "S3CheckFailed", Level = LogLevel.Error,
        Message = "Bucket {Bucket} on {Endpoint} answered HTTP {StatusCode} ({ErrorCode}). 403 means the credentials " +
                  "may not read it.")]
    public static partial void S3CheckFailed(this ILogger logger, string bucket, string endpoint, int statusCode, string errorCode);

    [LoggerMessage(EventId = 506, EventName = "BucketInAnotherRegion", Level = LogLevel.Error,
        Message = "Bucket {Bucket} isn't in {Region}. Set S3Source:Region to the bucket's region: in the S3 console, " +
                  "the bucket's Properties > AWS Region.")]
    public static partial void BucketInAnotherRegion(this ILogger logger, string bucket, string region);
}
